import importlib.machinery,sys,json,os,pathlib
class TritonOnly:
    def find_spec(self,fullname,path=None,target=None):
        if fullname=='triton' and path is None:
            return importlib.machinery.PathFinder.find_spec(fullname,['/home/pc/anaconda3/envs/DS/lib/python3.12/site-packages'])
sys.meta_path.insert(0,TritonOnly())
import torch,triton,triton.language as tl
from benchmarks.atlasfold.profile_inference import resolve_physical_device,_GpuProcessMonitor
@triton.jit
def copy_kernel(x,y,N:tl.constexpr,B:tl.constexpr):
    i=tl.program_id(0)*B+tl.arange(0,B)
    tl.store(y+i,tl.load(x+i,i<N,other=0),i<N)
torch.cuda.init();device=resolve_physical_device();mon=_GpuProcessMonitor(device['gpu'],os.getpid(),1);mon.start()
r={'device':device,'torch':str(torch.__version__),'torch_path':torch.__file__,'triton':triton.__version__,'triton_path':triton.__file__}
try:
 r['target']=str(triton.runtime.driver.active.get_current_target())
 x=torch.randn(8193,device='cuda');y=torch.empty_like(x);copy_kernel[(triton.cdiv(x.numel(),256),)](x,y,x.numel(),256);torch.cuda.synchronize();assert torch.equal(x,y)
 from openfold3.core.kernels.triton.evoformer import _TRITON_AVAILABLE
 assert _TRITON_AVAILABLE;r['status']='complete';r['copy_equal']=True
finally:
 r['isolation']=mon.stop();p=pathlib.Path('/media/IntelSSD/fireprot/outputs/openfold3/triton-environment-probe.json');p.write_text(json.dumps(r,indent=2));print(json.dumps(r))
